import { NextResponse } from "next/server";
import { fetchOrderByEmailAndNumber } from "@/lib/commerce";
import { fetchDelhiveryTrackingEvent } from "@/lib/delhivery";
import { resolveShippingPresentation } from "@/lib/shippingProgress";
export async function POST(request: Request) { try { const { email, orderNumber } = await request.json(); const safeEmail = String(email || "").trim().toLowerCase(); const safeNumber = String(orderNumber || "").replace(/^#/, "").trim(); if (!/^\S+@\S+\.\S+$/.test(safeEmail) || !/^\d{1,12}$/.test(safeNumber)) return NextResponse.json({ error: "Enter a valid order number and email." }, { status: 400 }); const order = await fetchOrderByEmailAndNumber(safeEmail, safeNumber); if (!order) return NextResponse.json({ error: "We couldn't find your order. Please check your details and try again." }, { status: 404 }); const tracking = order.tracking?.[0]; const event = tracking?.number ? await fetchDelhiveryTrackingEvent({ trackingNumber: tracking.number, company: tracking.company }) : null; const shipping = resolveShippingPresentation({ fulfillmentStatus: order.fulfillmentStatus, fulfillmentOrderStatuses: order.fulfillmentOrderStatuses, hasTracking: Boolean(tracking?.number || tracking?.url), tags: order.tags, fulfillmentEvents: event ? [event] : order.fulfillmentEvents || [] }); return NextResponse.json({ orderNumber: `#${order.orderNumber}`, orderDate: order.processedAt, fulfillmentStatus: shipping.label, trackerCaption: shipping.trackerCaption, trackingNumber: tracking?.number || "", shippingCarrier: tracking?.company || "", currentStep: shipping.step }); } catch (error) { return NextResponse.json({ error: (error as Error).message || "Unable to track order." }, { status: 500 }); } }
